test('accepts lines written as `export KEY=value`', () => {
  const env = new EnvAccessor('export HOST=localhost\nexport   PORT=3000\nexport\tMODE=dev\n');
  assert.deepEqual(env.all(), { HOST: 'localhost', PORT: '3000', MODE: 'dev' });
  assert.equal(env.has('export HOST'), false);
});

test('an exported value is still unquoted', () => {
  const env = new EnvAccessor('export A="one two"\nexport B=\'three\'\n');
  assert.equal(env.get('A'), 'one two');
  assert.equal(env.get('B'), 'three');
});

test('only a leading `export ` is dropped', () => {
  const env = new EnvAccessor('export=1\nexported=2\n  export  PADDED=3\n# export COMMENTED=4\nA=export B=5\n');
  assert.deepEqual(env.all(), { export: '1', exported: '2', PADDED: '3', A: 'export B=5' });
});
